new Promise((resolve, reject) => {
    CR.Core.ajaxRequest({
        url: 'DirectXMLPostJSON',
        xmlData: $XML$.getXMLDocument(),
        success: function(response) {
            const data = CR.JSON.parse(response.responseText);
            resolve(data);
        },
        failure: function(error) {
            reject(error);
        }
    });
})

async function $NAME$($PARAM$) {
    const xml = new CR.XML();
    const sequence = xml.addContainer(xml.getRootElement(), 'sequence');
    const transaction = xml.addContainer(sequence, 'transaction');
    const step = xml.addContainer(transaction, 'step');
    const record = xml.addContainer(step, 'record');
    xml.addText(record, 'tableName', '$TABLE$');
    xml.addOption(record, 'operation', 'V');
    xml.addText(record, 'targetSerial', $PARAM$);
    xml.addOption(record, 'includeAllColumns', 'Y');

    return new Promise((resolve, reject) => {
        CR.Core.ajaxRequest({
            url: 'DirectXMLPostJSON',
            xmlData: xml.getXMLDocument(),
            success: function(response) {
                const records = [];
                const errors = [];
                const data = CR.JSON.parse(response.responseText);
                const query = data.query;
                if (query) {
                    Ext.each(query.sequence, (seq) => {
                        Ext.each(seq.transaction, (tran) => {
                            Ext.each(tran.exception, (ex) => errors.push(ex.message));
                            Ext.each(tran.step, (s) => {
                                if (s.record) records.push(s.record);
                            });
                        });
                    });
                }
                if (errors.length) reject(errors);
                else resolve(records);
            },
            failure: reject
        });
    });
}

const responseJson = CR.JSON.parse($RESPONSE$.responseText);
const query = responseJson.query;
const records = [];
const errors = [];
if (query) {
    Ext.each(query.sequence, (sequence) => {
        Ext.each(sequence.transaction, (transaction) => {
            Ext.each(transaction.exception, (ex) => errors.push(ex.message));
            Ext.each(transaction.step, (step) => {
                if (step.record) records.push(step.record);
            });
        });
    });
}
$END$

const $STORE$ = new Ext.data.JsonStore({
    fields: [
        { name: '$FIELD1$', type: 'string' },
        { name: '$FIELD2$', type: 'string' },
    ],
    data: []
});

const $GRID$ = new CR.GridPanel({
    title: '$TITLE$',
    store: $STORE$,
    columns: [
        { header: '$FIELD1$', dataIndex: '$FIELD1$', width: 100 },
        { header: '$FIELD2$', dataIndex: '$FIELD2$', width: 200 },
    ],
    autoExpandColumn: '$FIELD2$',
    stripeRows: true,
    height: $HEIGHT$,
    listeners: {
        rowclick: function(grid, rowIndex) {
            const record = grid.getStore().getAt(rowIndex);
            $END$
        }
    }
});

const $GRID$ = new CR.EditorGridPanel({
    title: '$TITLE$',
    crColumns: [
        { header: '$COLUMN$', dataIndex: '$FIELD$', width: 150,
          editor: new Ext.form.TextField() },
    ],
    crAutoCommit: false,
    clicksToEdit: 1,
    height: $HEIGHT$,
    tbar: [
        { text: 'Add Row', handler: function() { $GRID$.crAddRow(); } },
        { text: 'Remove', handler: function() { $GRID$.crRemoveSelected(); } },
        '-',
        { text: 'Save', handler: function() {
            const modified = $GRID$.crGetModifiedRecords();
            $END$
        }},
    ]
});

const $FORM$ = new CR.FormPanel({
    title: '$TITLE$',
    labelWidth: $LABELWIDTH$,
    bodyStyle: 'padding: 10px',
    defaultType: 'textfield',
    items: [
        new CR.TextField({
            crColumnName: '$TEXTFIELD$',
            crColumnDescription: '$TEXTLABEL$',
            width: 250
        }),
        new CR.DateField({
            crColumnName: '$DATEFIELD$',
            crColumnDescription: '$DATELABEL$'
        }),
        new CR.MoneyField({
            crColumnName: '$MONEYFIELD$',
            crColumnDescription: '$MONEYLABEL$'
        }),
    ],
    buttons: [
        { text: 'Save', handler: function() {
            const fields = CR.Core.findFields($FORM$);
            $END$
        }},
        { text: 'Cancel', handler: function() { $FORM$.crFocusFirstField(); } }
    ]
});

const $TABS$ = new CR.TabPanel({
    activeTab: 0,
    region: '$REGION$',
    items: [
        {
            title: '$TAB1$',
            layout: 'fit',
            items: [$END$]
        },
        {
            title: '$TAB2$',
            layout: 'fit',
            items: []
        }
    ]
});

const panel = new CR.Panel({
    region: 'center',
    layout: '$LAYOUT$',
    items: [$END$]
});

CR.Core.viewPort = new Ext.Viewport({
    layout: 'border',
    renderTo: CR.Script.scriptDefaultPanelId,
    items: [panel]
});

const searchXml = new CR.XML();
const seq = searchXml.addContainer(searchXml.getRootElement(), 'sequence');
const tran = searchXml.addContainer(seq, 'transaction');
const step = searchXml.addContainer(tran, 'step');
const search = searchXml.addContainer(step, 'search');
searchXml.addText(search, 'tableName', '$TABLE$');
searchXml.addText(search, 'filterName', '$FILTER$');
searchXml.addOption(search, 'includeSelectColumns', 'Y');
searchXml.addOption(search, 'includeTotalHitCount', 'Y');
searchXml.addText(search, 'returnLimit', $LIMIT$);
const param = searchXml.addContainer(search, 'parameter');
searchXml.addText(param, 'contents', $QUERY$);

CR.Core.ajaxRequest({
    url: 'SearchJSON',
    xmlData: searchXml.getXMLDocument(),
    success: function(response) {
        const data = CR.JSON.parse(response.responseText);
        $END$
    }
});
